package com.smritisathi.app.core;
import android.app.*;import android.os.*;import android.view.*;import android.widget.*;import android.net.*;import android.content.*;
public abstract class BaseActivity extends Activity { protected LinearLayout root; @Override public void onCreate(Bundle b){super.onCreate(b);root=UI.page(this);ScrollView scroll=new ScrollView(this);scroll.addView(root);setContentView(scroll);} public void header(String title){root.addView(UI.title(this,title));} public void offlineBanner(){if(!isOnline()){TextView t=UI.text(this,"Offline Mode — changes will sync later");t.setTextColor(0xffffffff);t.setBackgroundColor(0xffdd6b20);t.setGravity(17);root.addView(t,0);}} boolean isOnline(){ConnectivityManager cm=(ConnectivityManager)getSystemService(CONNECTIVITY_SERVICE);Network n=cm.getActiveNetwork();return n!=null&&cm.getNetworkCapabilities(n)!=null&&cm.getNetworkCapabilities(n).hasCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET);} public void back(){finish();}}
